from pathlib import Path
import sys
sys.path.insert(0, str(Path.cwd() / "tests"))
import mountainash as ma
from fixtures.backend_helpers import BackendDataFrameFactory

for provider in ("polars", "ibis-sqlite"):
    frame = BackendDataFrameFactory.create({"val": [1.0, float("nan"), None]}, provider)
    for method in ("is_nan", "is_not_nan", "fill_nan"):
        expression = getattr(ma.col("val"), method)(0.0) if method == "fill_nan" else getattr(ma.col("val"), method)()
        try:
            result = ma.relation(frame).select(expression.alias("result")).to_dict()["result"]
            print(provider, method, "public", result)
        except Exception as error:
            print(provider, method, "public error", type(error).__module__ + "." + type(error).__qualname__, str(error))
    if provider == "ibis-sqlite":
        print("native input null flags", frame.select(frame.val.isnull().name("is_null")).execute()["is_null"].tolist())
        for method in ("is_not_nan", "fill_nan"):
            expression = ~frame.val.isnan() if method == "is_not_nan" else frame.val.isnan().ifelse(0.0, frame.val)
            try:
                result = frame.select(expression.name("result")).execute()["result"].tolist()
                print(provider, method, "direct-native", result)
            except Exception as error:
                print(provider, method, "direct-native error", type(error).__module__ + "." + type(error).__qualname__, str(error))
